import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Alpha status","description":"","frontmatter":{},"headers":[],"relativePath":"alpha-status.md","filePath":"alpha-status.md","lastUpdated":1793722140000}'),d={name:"alpha-status.md"};function s(i,e,n,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="alpha-status" tabindex="-1">Alpha status <a class="header-anchor" href="#alpha-status" aria-label="Permalink to &quot;Alpha status&quot;">​</a></h1><p>kernl is a first draft. This page says what runs, what is a contract without an implementation, and which gaps have been filed against upstream. It is updated in the same pull request as the code it describes.</p><h2 id="what-works" tabindex="-1">What works <a class="header-anchor" href="#what-works" aria-label="Permalink to &quot;What works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Package</th><th>State</th></tr></thead><tbody><tr><td>Guard</td><td><code>@kernl/guard</code></td><td>Three profiles (<code>createGuardConfig</code>, <code>applyNappletRules</code>), envelope classification, ingress flood control with quarantine, visibility gate, focus-aware firewall over <code>@kehto/firewall</code>&#39;s <code>evaluate()</code>, the fixed zero-network CSP, eleven mitigation descriptions for the UI. Pure, fully specified in <code>packages/guard/features/</code>.</td></tr><tr><td>Messaging</td><td><code>@kernl/messaging</code></td><td><code>MessagingProvider</code>, <code>MessagingBackend</code>, <code>MessagingRegistry</code> with saved-preference restore, the composite backend with <code>provider:innerId</code> namespacing, <code>describeProvider</code> rows, a complete in-memory backend (<code>createMemoryBackend</code>) used by the preview and the tests, and three providers (<code>private</code>, <code>legacy</code>, <code>ratchet</code>) built with <code>defineProvider</code> from backends the shell injects.</td></tr><tr><td>Bridges</td><td><code>@kernl/bridges</code></td><td><code>Locator</code> parsing for the web schemes, <code>magnet:</code>, <code>nzb:</code>, <code>slsk:</code> and <code>mailto:</code>, the <code>Bridge</code> contract, the registry with its <code>authorize</code> hook and outcome events, a complete HTTP bridge with SSRF policy, the four backend-driven bridges up to their backend interface, <code>createBridgeResourceResolver</code> for kehto&#39;s resource service, and <code>describeBridge</code> rows.</td></tr><tr><td>Composition</td><td><code>@kernl/core</code></td><td><code>createKernl</code> over one applesauce <code>EventStore</code>, <code>RelayPool</code> and <code>AccountManager</code>, with kehto&#39;s real <code>createShellBridge</code> exercised end to end in <code>kernl.feature</code>: an applet is decoded, resolved, planned and mounted, binds its port through the guarded <code>handleWindowMessage</code>, completes <code>shell.ready</code>, is answered by the theme, identity and resource services, and is quarantined and revoked when it floods. Relay tiers, the applesauce adapters, the guard pipeline and runtime firewall rules, grants over <code>bridge.runtime.aclState</code>, consent summaries, the default registries and the layouts each have their own feature file.</td></tr><tr><td>Shell UI</td><td><code>apps/web</code></td><td>Landing site at <code>/</code> and the shell at <code>/app/</code>: sign-in (browser extension, remote signer, read-only, password-protected local account), open by address with the required and optional domains as choices, windows, a grants panel per window, a shell-wide guard panel with the event log, the provider picker, and the offline preview behind <code>?preview=1</code> (D-011).</td></tr></tbody></table><p>&quot;Works&quot; means the behaviour has a scenario in <code>features/</code>, the scenario passes, and the page describing it exists. It does not mean the API is stable. Every package is <code>0.1.0</code>; on 0.x a breaking change is a minor bump.</p><h2 id="messaging-providers-in-the-live-shell" tabindex="-1">Messaging providers in the live shell <a class="header-anchor" href="#messaging-providers-in-the-live-shell" aria-label="Permalink to &quot;Messaging providers in the live shell&quot;">​</a></h2><p><code>createDefaultMessaging</code> registers all three providers, and each reports itself unavailable with a reason from <code>MESSAGING_UNAVAILABLE_REASONS</code> until the host passes a backend factory in <code>KernlOptions.messagingBackends</code>:</p><table tabindex="0"><thead><tr><th>Provider</th><th>Reason</th><th>What is missing</th></tr></thead><tbody><tr><td><code>private</code></td><td><code>needs-local-key-signer</code></td><td>kehto&#39;s sealed-message adapter wants the owner&#39;s raw secret key, which kernl never holds outside an applesauce signer. A backend built from a signer the host controls makes it available.</td></tr><tr><td><code>legacy</code></td><td><code>not-implemented</code></td><td>No backend exists for the original direct-message format.</td></tr><tr><td><code>ratchet</code></td><td><code>no-runtime</code></td><td>A double-ratchet runtime has to be supplied.</td></tr></tbody></table><p><code>apps/web</code> supplies none of them, so the live shell&#39;s provider picker shows all three greyed with these reasons. The preview uses the in-memory backend.</p><h2 id="what-does-not-work-yet" tabindex="-1">What does not work yet <a class="header-anchor" href="#what-does-not-work-yet" aria-label="Permalink to &quot;What does not work yet&quot;">​</a></h2><ul><li><strong>Transfer backends.</strong> <code>TorrentBackend</code>, <code>NzbBackend</code>, <code>SoulseekBackend</code> and <code>MailBackend</code> are interfaces. Without a backend the corresponding bridge reports <code>{ available: false, reason: &#39;no-backend&#39; }</code>, rejects with <code>unavailable:no-backend</code>, and the shell shows that. See <a href="./concepts/bridges#backend-driven-bridges">Bridges</a>.</li><li><strong>Real messaging backends.</strong> The table above. See <a href="./concepts/messaging">Messaging</a>.</li><li><strong>Per-host bridge consent.</strong> <code>createKernl</code> builds the bridge registry with <code>createDefaultBridges()</code> and no <code>authorize</code> hook, so a <code>resource</code> request from a granted applet is checked by the HTTP bridge&#39;s SSRF policy and nothing else. A host that wants a prompt per host or scheme passes its own registry in <code>KernlOptions.bridges</code>.</li><li><strong>Per-applet guard profiles.</strong> <code>GuardFacade.setProfile</code> rebuilds the pipeline for the whole shell and is not persisted. The per-applet, remembered override D-003 describes is not in this draft.</li><li><strong>Mobile layouts.</strong> The layouts are desktop tilings over <code>@kehto/wm</code>. Narrow viewports get a single stacked window without gestures.</li><li><strong>Multi-account switching.</strong> <code>AccountManager</code> holds several accounts and the sign-in panel lists them, but switching means signing out and in.</li><li><strong>Grant persistence across devices.</strong> Grants, relay tiers and messaging preferences persist in the host&#39;s storage only. There is no sync.</li><li><strong>Source links in the API reference.</strong> TypeDoc source links point at the repository only once a git remote is configured in the build environment.</li></ul><p>The <a href="./roadmap">Roadmap</a> orders this list.</p><h2 id="upstream-gaps" tabindex="-1">Upstream gaps <a class="header-anchor" href="#upstream-gaps" aria-label="Permalink to &quot;Upstream gaps&quot;">​</a></h2><p>kernl composes kehto rather than forking it (<a href="https://github.com/kernlize/web/blob/main/DECISIONS.md" target="_blank" rel="noreferrer">D-001</a>). Four seams in kehto are narrower than kernl wants. All four are filed against <code>kehto/web</code> rather than patched locally, and each has a kernl layer that shrinks when it lands (D-012):</p><ol><li><strong><code>ShellAdapter</code> does not forward <code>getFocusContext</code>, <code>onFirewallEvent</code> or <code>firewallPersistence</code> to the runtime.</strong> kernl runs its focus-aware firewall in <code>@kernl/guard</code>, in front of the bridge for the window-level <code>hello</code> and reactively for port traffic, using the pure <code>evaluate()</code> engine with visibility supplied by the host. Because that layer never supplies <code>initElapsedMs</code>, kehto&#39;s init-burst guard does not fire there; the per-second burst is the ingress guard&#39;s, and <code>createGuardConfig</code> sets <code>firewall.burstGuard</code> to match.</li><li><strong><code>createRuntime</code> hardcodes the ACL default policy to <code>&#39;permissive&#39;</code>.</strong> kernl produces its restrictive posture with <code>KernlGrants.ensure</code>, which writes an explicit grant or revoke for every capability of every applet it plans, plus <code>capabilities.resolveEnvironment</code>, which narrows the advertised domains to the baseline and the user&#39;s grants. The permissive default is never reached for an applet kernl runs.</li><li><strong>There is no pre-dispatch hook on port traffic.</strong> <code>onNappletMessage</code> is observe-only, so kernl&#39;s ingress guard, visibility gate and focus firewall see a port envelope after the runtime dispatched it. Pre-dispatch limits come from the runtime&#39;s own firewall, configured through <code>applyRuntimeFirewallRules</code>; deferral while hidden is advisory for port traffic. See <a href="./concepts/guard#where-enforcement-happens">Guard</a>.</li><li><strong><code>FirewallStateContainer</code> has no setter for <code>unfocusedMultiplier</code>.</strong> The runtime firewall applies kehto&#39;s default multiplier before dispatch; the profile&#39;s value is applied only by kernl&#39;s reactive focus firewall.</li></ol><p>A fifth observation, not a gap kernl needs closed: the transport internals <code>createNip5dTransport</code> and <code>createShellReadyState</code> are not exported, so kernl uses <code>createShellBridge</code> unchanged.</p><h2 id="versions-this-draft-is-built-against" tabindex="-1">Versions this draft is built against <a class="header-anchor" href="#versions-this-draft-is-built-against" aria-label="Permalink to &quot;Versions this draft is built against&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dependency</th><th>Range</th></tr></thead><tbody><tr><td><code>@kehto/acl</code></td><td><code>^0.20.2</code></td></tr><tr><td><code>@kehto/firewall</code></td><td><code>^0.6.3</code></td></tr><tr><td><code>@kehto/runtime</code></td><td><code>^0.27.2</code></td></tr><tr><td><code>@kehto/shell</code></td><td><code>^0.29.0</code></td></tr><tr><td><code>@kehto/services</code></td><td><code>^0.29.0</code></td></tr><tr><td><code>@kehto/nip</code></td><td><code>^0.8.0</code></td></tr><tr><td><code>@kehto/wm</code></td><td><code>^0.0.2</code></td></tr><tr><td><code>applesauce-*</code></td><td><code>^7.0.x</code></td></tr><tr><td><code>@napplet/core</code></td><td><code>&gt;=0.37.0 &lt;0.38.0</code></td></tr></tbody></table><p>The protocol itself is a draft. NIP-5D is <a href="https://github.com/nostr-protocol/nips/pull/2303" target="_blank" rel="noreferrer">nostr-protocol/nips PR #2303</a> and the NAP documents live at <a href="https://github.com/napplet/naps" target="_blank" rel="noreferrer">napplet/naps</a>. kernl keeps no local copy of either; see <a href="./policies/spec-conformance">Spec conformance</a>.</p>',19)])])}const g=t(d,[["render",s]]);export{u as __pageData,g as default};
